/** Call only after BOTH hook configurations have the record and workers are stopped. */
export async function completePairing(options = {}) {
  if (options.hostsStopped !== true || !CLIENTS.every(client => options.configured?.[client] === true)) fail('binding_configuration_required');
  return locked({ ...options, setup: true }, async ({ install, record, locations, keys }, liveness) => {
    if (install.resetPending) fail('identity_reset_pending');
    if (!record || !install.shared?.initialized || !install.shared.barrier ||
        install.shared.id !== record.id || install.shared.root !== record.root ||
        record.namespace !== liveness.namespace) fail('pending_binding_mismatch');
    if (!keys.includes(record.root)) return disabled('paired_key_missing');
    for (const client of CLIENTS) install.clients[client] = { root: record.root, state: 'established' };
    install.shared.ready = true;
    await saveInstall(locations, install);
    return { status: 'paired', enabled: true, pairingRecord: locations.pairing, root: record.root };
  });
}

/** Explicit stopped-worker identity reset; old roots and memories are retained. */
