    if (!install.shared || (!record && !install.resetPending) || options.root === install.shared.root ||
        (keys.includes(options.root) && !install.resetPending)) fail('identity_reset_requires_new_root');
    if (install.resetPending && install.resetPending.root !== options.root) fail('pending_binding_mismatch');
    install.resetPending = { root: options.root, client: options.primaryClient };
    await saveInstall(locations, install);
    await projectKey(options.root);
    await setPaused(options.root, true, { rotate: true });
    const retired = [...(install.retired ?? []), { ...install.shared, invalidated: true }];
    await unlink(locations.pairing).catch(error => { if (error.code !== "ENOENT") throw error; });
